\begin{aligned}
& J_\sigma(\epsilon_) :=
   \bb{E}_{\vx_{0:T} \sim q_\sigma(\vx_{0:T})}[\log q_\sigma(\vx_{1:T} | \vx_0) - \log p_(\vx_{0:T})] \\
   = & \ \bb{E}_{\vx_{0:T} \sim q_\sigma(\vx_{0:T})} \left[\log q_\sigma(\vx_T | \vx_0) + \sum_{t=2}^{T} \log q_\sigma(\vx_{t-1} | \vx_t, \vx_0) - \sum_{t=1}^{T} \log p_^{(t)}(\vx_{t-1} | \vx_t) - \log p_(\vx_T) \right]
\end{aligned}

\begin{aligned}
J_\sigma(\epsilon_) & := \bb{E}_{\vx_{0:T} \sim q(\vx_{0:T})} \left[\log q_\sigma(\vx_T | \vx_0) + \sum_{t=2}^{T} \log q_\sigma(\vx_{t-1} | \vx_t, \vx_0) - \sum_{t=1}^{T} \log p_^{(t)}(\vx_{t-1} | \vx_t) \right] \\
   & \equiv \bb{E}_{\vx_{0:T} \sim q(\vx_{0:T})} \left[\sum_{t=2}^{T} \KL(q_\sigma(\vx_{t-1} | \vx_t, \vx_0)) \Vert p_^{(t)}(\vx_{t-1} | \vx_t)) - \log p_^{(1)}(\vx_0 | \vx_1)  \right]
\end{aligned}

\begin{aligned}
& \ \bb{E}_{\vx_{0}, \vx_1 \sim q(\vx_{0}, \vx_1)} \left[ - \log p_^{(1)}(\vx_0 | \vx_1)  \right] \equiv \bb{E}_{\vx_{0}, \vx_1 \sim q(\vx_{0}, \vx_1)}\left[\frac{\norm{\vx_0 - f_{}^{(t)}(\vx_1)}_2^2}{2 \sigma_1^2}\right] \\
   = & \ \bb{E}_{\vx_{0} \sim q(\vx_{0}), \epsilon \sim \gN(\vzero, \mI), \vx_1 = \sqrt{\alpha_1} \vx_0 + \sqrt{1 - \alpha_t} \epsilon}\left[\frac{\norm{\epsilon - \epsilon_{}^{(1)}(\vx_1)}_2^2}{2 d \sigma_1^2 \alpha_1}\right]
\end{aligned}

\begin{aligned}
J(\epsilon_) & = \bb{E}_{\vx_{0:T} \sim q_{\sigma, \tau}(\vx_{0:T})}[ \log q_{\sigma, \tau}(\vx_{1:T} | \vx_0) - \log p_(\vx_{0:T})] \\
   & =\bb{E}_{\vx_{0:T} \sim q_{\sigma, \tau}(\vx_{0:T})}\Bigg[ \sum_{t \in \bar{\tau}} \KL(q_{\sigma, \tau}(\vx_{t} | \vx_0) \Vert p_^{(t)}(\vx_0 | \vx_{t}) \\
   & \qquad \qquad \qquad \qquad + \sum_{i=1}^{L} \KL(q_{\sigma, \tau}(\vx_{\tau_{i-1}} | \vx_{\tau_{i}}, \vx_0) \Vert p_^{(\tau_i)}(\vx_{\tau_{i-1}} | \vx_{\tau_i})) ) \Bigg]
\end{aligned}

\begin{aligned}
{\color{teal} L} & := \bb{E}_{\vx_{0:T} \sim q(\vx_{0:T})} \left[q(\vx_T | \vx_0) + \sum_{t=2}^{T} \log q(\vx_{t-1} | \vx_t, \vx_0) - \sum_{t=1}^{T} \log p_^{(t)}(\vx_{t-1} | \vx_t) \right] \\
   & \equiv \bb{E}_{\vx_{0:T} \sim q(\vx_{0:T})} \left[\sum_{t=2}^{T} \underbrace{\KL(q(\vx_{t-1} | \vx_t, \vx_0)) \Vert p_^{(t)}(\vx_{t-1} | \vx_t))}_{\color{teal} L_{t-1}} - \log p_^{(1)}(\vx_0 | \vx_1) \right]
\end{aligned}
